{
  "name": "rx_update_ewma",
  "confidence": "medium",
  "docstring": "Updates a 16-bit exponential moving average from a fixed-point ratio of two buffer fields, using a saturating counter for zero samples and an init flag for the first valid average.",
  "subsystem": "ble",
  "var_renames": {
    "v1": "prev_value",
    "v3": "scaled_current",
    "v4": "ratio",
    "v5": "zero_count"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "previous/denominator value; zero indicates missing sample"
    },
    {
      "offset": 2,
      "meaning": "current/numerator value scaled by 65536"
    },
    {
      "offset": 4,
      "meaning": "16-bit moving average"
    },
    {
      "offset": 8,
      "meaning": "saturating counter of consecutive zero/invalid samples"
    },
    {
      "offset": 9,
      "meaning": "moving-average initialized flag"
    }
  ]
}
